use super::{builtin_agent_types, is_generated_agent_type, render_claude_agent_type};

#[test]
fn worker_type_renders_marker_as_first_body_line() {
    let rendered = render_claude_agent_type(&builtin_agent_types()[0], b"LANE\n");
    assert_eq!(
        rendered,
        "\
---
name: vibe-worker
description: Use for any worker that needs this project's full context (its rules, specs and boot lane), such as research, review or design without a task packet. Workers of this type share one cached system prompt.
---
<!-- Generated by vibe; do not edit. vibe rewrites this file at every vibe agent claude launch and on vibe prompt types. -->

You are a full-context worker started by a lead session in this project. The project's composed boot lane follows. It is already in your context, so do not read its files from disk again. Do the task the lead gives you and report back to the lead.

LANE
"
        .as_bytes(),
    );
}

#[test]
fn executor_type_has_no_preface() {
    let rendered = render_claude_agent_type(&builtin_agent_types()[1], b"RULES\n");
    assert_eq!(
        rendered,
        "\
---
name: vibe-executor
description: Use for every executor given one task packet. It follows the packet and the executor rules only, without the project boot lane; the packet must carry the subagent quiet clause.
---
<!-- Generated by vibe; do not edit. vibe rewrites this file at every vibe agent claude launch and on vibe prompt types. -->

RULES
"
        .as_bytes(),
    );
}

#[test]
fn foreign_file_is_not_generated() {
    let types = builtin_agent_types();
    let worker = render_claude_agent_type(&types[0], b"LANE\n");
    let executor = render_claude_agent_type(&types[1], b"RULES\n");
    assert!(is_generated_agent_type(&worker));
    assert!(is_generated_agent_type(&executor));
    let worker_crlf = String::from_utf8(worker).unwrap().replace('\n', "\r\n");
    assert!(is_generated_agent_type(worker_crlf.as_bytes()));
    for foreign in [
        "---\nname: opus5\ndescription: x\n---\nYou are...\n",
        "",
        "<!-- Generated by vibe; do not edit. vibe rewrites this file at every vibe agent claude launch and on vibe prompt types. -->\n",
    ] {
        assert!(!is_generated_agent_type(foreign.as_bytes()));
    }
}
